<?php
namespace App\Http\Controllers;
use App\Models\SiteSetting;use Illuminate\Http\Request;
class AdminStoreSettingsController extends Controller{public function edit(){ $social=json_decode((string)SiteSetting::getValue('social_links','{}'),true)?:[];$badges=json_decode((string)SiteSetting::getValue('trust_badges','[]'),true)?:[];return view('admin.store-settings',compact('social','badges'));}public function update(Request $request){$data=$request->validate(['eitaa'=>'nullable|url','rubika'=>'nullable|url','bale'=>'nullable|url','telegram'=>'nullable|url','instagram'=>'nullable|url','linkedin'=>'nullable|url','aparat'=>'nullable|url','badge1_title'=>'nullable|string|max:100','badge1_image'=>'nullable|url','badge1_url'=>'nullable|url','badge2_title'=>'nullable|string|max:100','badge2_image'=>'nullable|url','badge2_url'=>'nullable|url']);$social=[];foreach(['eitaa','rubika','bale','telegram','instagram','linkedin','aparat'] as $k)$social[$k]=$data[$k]??'';$badges=[];foreach([1,2] as $i)if(!empty($data["badge{$i}_image"]))$badges[]=['title'=>$data["badge{$i}_title"]??'نماد','image'=>$data["badge{$i}_image"],'url'=>$data["badge{$i}_url"]??'#'];SiteSetting::putValue('social_links',json_encode($social,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));SiteSetting::putValue('trust_badges',json_encode($badges,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));return back()->with('success','تنظیمات فوتر ذخیره شد.');}}
